 let state=store.load(validateAppState,freshState),pendingCheckpoint=null,checkpointStamp=0,lastIndex=-1,completionRecorded=false,audio=null,wakeLock=null,view='workout',filter='all',toastHandle,plan=null,planMessage='',lastCompletedId=null;
