 function showView(name,update=true){if(name==='welcome'||['signup','login','reset','device'].includes(name)||name.startsWith('setup/'))return;view=['home','discover','workout','plan','library','progress','settings'].includes(name)?name:'home';doc.querySelectorAll('.view').forEach(e=>e.hidden=e.id!=='view-'+view);doc.querySelectorAll('[data-view]').forEach(e=>{const active=e.dataset.view===view;e.classList.toggle('active',active);if(active)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});$('breadcrumb').textContent='YOUR TRAINING SPACE / '+(view==='workout'?'TODAY':view.toUpperCase());if(update)try{win.history.replaceState(null,'','#'+view);}catch{}if(view!=='workout'&&timer.status==='running'){timer.pause();releaseWakeLock();renderTimer();toast('Session paused. Return to Workout to resume.');}if(view!=='workout')fitness?.stopVoice();if(view==='home')home?.render();win.scrollTo({top:0,behavior:'instant'});}
