 function choosePersonalized(){if(pendingCheckpoint){toast('Resume or discard your saved session first.');return;}if(timer.elapsed>0&&timer.status!=='complete'&&!win.confirm('Replace the unfinished session? It will not be logged.'))return;try{const last=state.workouts.at(-1);const next=todayDescriptor();const recovery=last?.soreness>=4&&last.date===dateKey();replaceTimer('personalized',recovery?recommendedSession(state.profile,1,{recovery:true}):next);$('session-context').textContent=recovery?'A lighter session after your latest soreness feedback.':'Matched to your preferences and available time.';}catch(error){toast(error.message);}}
 function renderJourney(){const p=state.profile,today=dateKey(),elapsed=Math.max(0,daysBetween(p.startDate,today)),total=daysBetween(p.startDate,p.deadline);$('journey-fill').style.width=Math.max(0,Math.min(100,elapsed/total*100))+'%';$('journey-caption').textContent=`${Math.ceil(total/7)} weeks · ${shortDate(p.deadline)}`;$('day-number').textContent=String(elapsed+1).padStart(2,'0');$('greeting-title').textContent=p.name?`Your next step, ${p.name}.`:'Your goals. Your pace.';$('workout-intro').textContent=p.coaching==='quiet'?'Your session is ready.':'Choose a manageable step and give yourself room to grow.';$('setup-banner').hidden=p.safetyAccepted;$('sidebar-goal').textContent='Your preferences ↗';}
 function renderWeek(){const w=weeklyStats(),d=new Date(),offset=(d.getDay()+6)%7,first=new Date(d.getFullYear(),d.getMonth(),d.getDate()-offset);$('weekly-sessions').textContent=w.complete.length;$('weekly-habit-copy').textContent=`${state.profile.days.length} planned days · recovery included`;$('week-days').innerHTML=Array.from({length:7},(_,i)=>{const day=new Date(first);day.setDate(day.getDate()+i);const key=dateKey(day),done=w.complete.some(x=>x.date===key);return `<div class="week-day ${key===dateKey()?'today':''} ${done?'done':''}" title="${esc(shortDate(key))}">${['M','T','W','T','F','S','S'][i]}<span>${done?'✓':day.getDate()}</span></div>`;}).join('');$('weekly-strength-days').textContent=w.strengthDays;$('weekly-days-target').textContent=` / ${state.profile.days.length} planned days`;$('weekly-strength-fill').style.width=Math.min(100,w.strengthDays/state.profile.days.length*100)+'%';$('weekly-brisk-minutes').textContent=w.briskMinutes;}
 function weekRanges(weeks){const groups=[];for(const week of weeks){const last=groups.at(-1);if(last&&week===last[1]+1)last[1]=week;else groups.push([week,week]);}return groups.map(([first,last])=>first===last?first:first+'-'+last).join(', ');}
 function renderPlan(){const p=state.profile,g=GOALS[p.goalType];$('plan-timeframe').textContent=`${shortDate(p.startDate)} to ${shortDate(p.deadline)} · ${Math.ceil(daysBetween(p.startDate,p.deadline)/7)} weeks · ${p.sessionMinutes}-minute sessions`;$('plan-goal-title').textContent=g.title;$('pace-copy').textContent=plan?.explanation||g.description;$('initial-target-note').textContent=p.targetValue===null?'No numeric target: focus on a routine that works for you.':`Your chosen target: ${p.targetValue} ${p.targetUnit}. Results vary; adjust as you learn.`;$('plan-error').hidden=!planMessage;$('plan-error').textContent=planMessage;
  const names=plan?.phaseNames||[];$('phase-cards').innerHTML=names.map((phase,i)=>{const weeks=[...new Set(plan.sessions.filter(x=>x.phase===phase).map(x=>x.week))];if(!weeks.length)return '';return `<article class="card phase-card"><span class="phase-number">${String(i+1).padStart(2,'0')}</span><span class="eyebrow">WEEKS ${weekRanges(weeks)}</span><h2>${esc(phase)}</h2><p>${phase==='Lighter week'?'Lower work and more recovery keep the routine sustainable.':'Practice controlled movement at a pace matched to your starting level.'}</p><span class="phase-tag">${p.sessionMinutes} minutes · ${esc(g.label)}</span></article>`;}).join('');
  const selected=$('plan-week-select').value||'1';$('plan-week-select').innerHTML=Array.from({length:plan?.weeks||0},(_,i)=>`<option value="${i+1}">Week ${i+1}</option>`).join('');$('plan-week-select').value=Number(selected)<=(plan?.weeks||0)?selected:'1';renderCalendar();renderWeek();}
 function renderCalendar(){if(!plan){$('plan-calendar').innerHTML='<p>Update your preferences to see a compatible schedule.</p>';return;}const week=Number($('plan-week-select').value)||1,entries=plan.sessions.filter(s=>s.week===week);$('plan-calendar').innerHTML=entries.map(s=>{const done=state.workouts.some(w=>w.date===s.date&&w.skipped===0);return `<div class="scheduled-session ${s.recovery?'recovery-session':''}"><div><span class="eyebrow">${esc(shortDate(s.date))}${done?' · COMPLETE':''}</span><strong>${esc(s.title)}</strong><small>${esc(s.phase)} · ${s.minutes} min${s.recovery?' · Recovery':''}</small></div><button class="outline-btn" data-plan-date="${s.date}">View session ↗</button></div>`;}).join('')||'<p>No training days in this part of the week. Rest and return to your next scheduled day.</p>';}
 function renderLineup(){const s=sessionInfo();$('session-title').textContent=s.title;const work=timer.steps.filter(x=>x.type==='work');const unique=[...new Set(work.map(x=>x.exercise))];$('rounds-summary').textContent=`${Math.round(timer.total/60)} min · ${unique.length} movements`;$('lineup').innerHTML=unique.map(id=>{const ex=EXERCISES[id],steps=work.filter(x=>x.exercise===id);return `<div class="lineup-item"><span class="lineup-icon">${movementArt(ex.art)}</span><div class="exercise-info"><strong>${esc(ex.name)}</strong><small>${esc(ex.subtitle)}</small></div><span class="duration">${steps.length} × ${steps[0].duration}s</span><button class="lineup-watch" data-demo="${id}" aria-label="Guide for ${esc(ex.name)}">${icon('play')}</button></div>`;}).join('');$('session-description').textContent=(s.description||'Controlled bodyweight movement for your chosen goal.')+' Activity windows are not repetition targets. Stop before your form slips.';doc.querySelectorAll('[data-session]').forEach(b=>b.classList.toggle('selected',b.dataset.session===timer.id));}
 function persistWorkout(){if(pendingCheckpoint)return;try{const draft=checkpointFor(timer);if(!draft){win.localStorage.removeItem(checkpointKey);return;}const now=Date.now();if(timer.status==='running'&&now-checkpointStamp<1000)return;win.localStorage.setItem(checkpointKey,JSON.stringify(draft));checkpointStamp=now;}catch{}}
