 $('start-timer').addEventListener('click',()=>{if(pendingCheckpoint){toast('Resume or discard your saved session first.');return;}if(!state.profile.safetyAccepted){openGoal();return;}try{if(state.profile.ageBand==='teen'&&ROUTINES.find(r=>r.id===timer.descriptor?.routineId)?.adultOnly){toast('Replace this adult body-shape routine with a strength or core session for teens.');return;}if(!sessionAllowed(state.profile,timer.steps)){toast('Update or replace this session to match your movement restrictions.');return;}}catch(error){toast(error.message);return;}enableAudio();if(timer.status==='running'){timer.pause();releaseWakeLock();}else{if(timer.status==='complete')replaceTimer();timer.start();fitness?.speak(timer.step);acquireWakeLock();}renderTimer();});
