 $('add-minute').addEventListener('click',()=>{if(timer.status==='running'){timer.tick();renderTimer();}if(!['rest','warmup','cooldown'].includes(timer.step.type)||timer.status==='complete')return;const extra=timer.step.type==='rest'?30:60;if(timer.total+extra>3600){toast('Pause for further rest; session extension is capped at one hour.');return;}timer.step.duration+=extra;timer.remaining+=extra;lastIndex=-1;renderTimer();renderLineup();});
